import { readFile, readdir, writeFile } from 'node:fs/promises';
const directory = new URL('../../backend/database/migrations/', import.meta.url);
const files = (await readdir(directory)).filter((name) => name.endsWith('.sql')).sort();
let sql = `-- FRESH SUPABASE PROJECT ONLY. Never run this bundle on an existing client database.
-- Generated by npm run db:prepare from checked-in migrations. Do not edit this file.
begin;
do $$ begin
  if to_regclass('public.inquiries') is not null then
    raise exception 'Existing application database: apply only new migrations, never INSTALL-FRESH.sql';
  end if;
end $$;
`;
for (const name of files) {
  const source = await readFile(new URL(name, directory), 'utf8');
  sql +=
    '\n-- Migration: ' + name + '\n' + source.replace(/^\s*(?:begin|commit);\s*$/gim, '') + '\n';
}
sql += '\ncommit;\n';
await writeFile(new URL('../../backend/database/INSTALL-FRESH.sql', import.meta.url), sql);
console.log('Ready: backend/database/INSTALL-FRESH.sql. Use once in your NEW Supabase project.');
